using System;
using System.Collections.Generic;
using System.Drawing;
using System.IO;
using System.Linq;
using System.Threading;
using System.Threading.Tasks;
using System.Windows.Forms;

namespace MacroExecute
{
    internal sealed class TestKeyboard : IKeyboardDesktop, IKeyboardState
    {
        public readonly List<string> Events=new List<string>();public Action<string> OnEvent;public readonly HashSet<int> Held=new HashSet<int>();public bool IsDown(int key){return Held.Contains(key);}
        private void Add(string value){Events.Add(value);if(OnEvent!=null)OnEvent(value);}
        public void Key(int key,bool up,bool extended){if(up)Held.Remove(key);else Held.Add(key);Add((up?"up:":"down:")+key);}
        public void Unicode(char value){Add("char:"+(int)value);}
    }
    internal sealed class TestClipboard : ITextClipboard
    {
        public string Value="original";public uint Version=1;public int Restores;
        public Func<string> ReadOverride;public string ReadText(){return ReadOverride==null?Value:ReadOverride();}public object Snapshot(){return Value;}public uint Sequence{get{return Version;}}
        public void SetText(string text){Value=text;Version++;}
        public void Restore(object value){Value=(string)value;Version++;Restores++;}
    }
    internal static class BehaviorTests
    {
        private static void Check(bool value,string message){if(!value)throw new Exception(message);}
        private static Task NoWait(int ms,CancellationToken token){token.ThrowIfCancellationRequested();return Task.FromResult(true);}
        private static IEnumerable<Control> Descendants(Control control){yield return control;foreach(Control child in control.Controls)foreach(var nested in Descendants(child))yield return nested;}
        public static void Run(Action<string,Action> test,string directory)
        {
            test("Legacy workflows retain inclusive matching, Unicode input and 30ms holds",delegate{var macro=Storage.Decode("{\"SchemaVersion\":1,\"Steps\":[{\"Kind\":10,\"Text\":\"hello\"}]}");var step=macro.Steps[0];Check(step.InputHoldMs==30&&step.TextIntervalMs==0&&step.TextEntry==TextEntryMode.Unicode&&step.ToleranceMode==ImageToleranceMode.InclusiveRgb&&!macro.RandomSeed.HasValue,"Legacy defaults changed");});
            test("Legacy RGB plus one is opt in and clamps at 255",delegate{foreach(int tolerance in new[]{0,1,254,255}){var step=new Step{Tolerance=tolerance};Check(Behavior.EffectiveTolerance(step)==tolerance,"Inclusive threshold changed");step.ToleranceMode=ImageToleranceMode.LegacyRgbPlusOne;Check(Behavior.EffectiveTolerance(step)==Math.Min(255,tolerance+1),"Legacy threshold wrong");}});
            test("Tolerance mode changes actual image IF matching without pointer movement",delegate{using(var desktop=new TestDesktop())using(var pattern=new Bitmap(1,1)){pattern.SetPixel(0,0,Color.FromArgb(254,0,0));var step=new Step{Kind=ActionKind.IfImage,ImageData=ImageTemplate.Encode(pattern),MoveToMatch=false};var images=new ImageSession(desktop);Check(!images.SearchOnce(step,CancellationToken.None).HasValue,"Exact matching accepted different RGB");step.ToleranceMode=ImageToleranceMode.LegacyRgbPlusOne;Check(images.SearchOnce(step,CancellationToken.None).HasValue,"Legacy mode missed one-channel boundary");}});
            test("Unicode text handles CRLF CR LF Tab accents and surrogate pairs",delegate{var keys=new TestKeyboard();var clipboard=new TestClipboard();var waits=new List<int>();TextPlayback.Run("é\r\nA\rB\n\t\U0001F680",new Step{TextIntervalMs=7},keys,clipboard,delegate(int n,CancellationToken t){waits.Add(n);return NoWait(n,t);},CancellationToken.None).GetAwaiter().GetResult();Check(keys.Events.Count(e=>e=="down:13")==3&&keys.Events.Count(e=>e=="down:9")==1,"Line ending or tab mapping wrong");Check(keys.Events.Contains("char:233")&&keys.Events.Contains("char:55357")&&keys.Events.Contains("char:56960"),"Unicode units lost");Check(waits.Count(n=>n==7)==8&&clipboard.Version==1,"Character pacing or clipboard changed");});
            test("Clipboard text restores original data after successful paste",delegate{var keys=new TestKeyboard();var clipboard=new TestClipboard();TextPlayback.Run("paste",new Step{TextEntry=TextEntryMode.ClipboardPaste},keys,clipboard,NoWait,CancellationToken.None).GetAwaiter().GetResult();Check(clipboard.Value=="original"&&clipboard.Restores==1&&keys.Events.SequenceEqual(new[]{"down:17","down:86","up:86","up:17"}),"Paste/restore sequence wrong");});
            test("Clipboard text never overwrites a newer external clipboard change",delegate{var clipboard=new TestClipboard();TextPlayback.Run("paste",new Step{TextEntry=TextEntryMode.ClipboardPaste},new TestKeyboard(),clipboard,delegate(int n,CancellationToken t){if(n>=100)clipboard.SetText("new user copy");return NoWait(n,t);},CancellationToken.None).GetAwaiter().GetResult();Check(clipboard.Value=="new user copy"&&clipboard.Restores==0,"New clipboard was overwritten");});
            test("Cancellation while paste holds keys releases both and restores clipboard",delegate{var keys=new TestKeyboard();var clipboard=new TestClipboard();using(var cancel=new CancellationTokenSource()){try{TextPlayback.Run("paste",new Step{TextEntry=TextEntryMode.ClipboardPaste},keys,clipboard,delegate(int n,CancellationToken t){cancel.Cancel();return NoWait(n,t);},cancel.Token).GetAwaiter().GetResult();throw new Exception("Cancellation ignored");}catch(OperationCanceledException){}Check(keys.Events.Contains("up:86")&&keys.Events.Last()=="up:17"&&clipboard.Value=="original","Paste cancellation cleanup missing");}});
            test("Empty text leaves clipboard and keyboard untouched",delegate{var keys=new TestKeyboard();var clipboard=new TestClipboard();TextPlayback.Run("",new Step{TextEntry=TextEntryMode.ClipboardPaste},keys,clipboard,NoWait,CancellationToken.None).GetAwaiter().GetResult();Check(keys.Events.Count==0&&clipboard.Version==1,"Empty text sent input");});
            test("Text cancellation stops before subsequent characters",delegate{var keys=new TestKeyboard();using(var cancel=new CancellationTokenSource()){keys.OnEvent=delegate{cancel.Cancel();};try{TextPlayback.Run("abc",new Step(),keys,new TestClipboard(),NoWait,cancel.Token).GetAwaiter().GetResult();}catch(OperationCanceledException){}Check(keys.Events.SequenceEqual(new[]{"char:97"}),"Text continued after cancellation");}});
            test("WindowsHost keyboard uses configurable hold and releases on cancellation",delegate{using(var ui=new Control())using(var desktop=new TestDesktop())using(var cancel=new CancellationTokenSource()){var keys=new TestKeyboard();var host=new WindowsHost(ui,desktop,keys,new TestClipboard());int hold=-1;host.Wait=delegate(int ms,CancellationToken t){hold=ms;cancel.Cancel();return NoWait(ms,t);};try{host.Execute(new Step{Kind=ActionKind.KeyPress,InputHoldMs=80},cancel.Token).GetAwaiter().GetResult();}catch(OperationCanceledException){}host.ReleaseInputs();Check(hold==80&&keys.Events.Last()=="up:65","Hold or release mismatch");}});
            test("Pause blocks text pacing until resumed and Stop remains responsive",delegate{using(var ui=new Control())using(var desktop=new TestDesktop())using(var cancel=new CancellationTokenSource()){var keys=new TestKeyboard();var host=new WindowsHost(ui,desktop,keys,new TestClipboard());var runner=new Runner(host);keys.OnEvent=delegate(string value){if(value=="char:97")runner.Paused=true;};var plan=Plan.Build(new Macro{Steps=new List<Step>{new Step{Kind=ActionKind.TypeText,Text="ab",TextIntervalMs=5}}},directory);Task playback=runner.Run(plan,1,1,cancel.Token);Task.Delay(80).GetAwaiter().GetResult();Check(keys.Events.SequenceEqual(new[]{"char:97"})&&!playback.IsCompleted,"Pause did not suspend text");runner.Paused=false;playback.GetAwaiter().GetResult();Check(keys.Events.Contains("char:98"),"Resume lost text");}});
            test("Fixed seed reproduces randomized repeat counts across playback runs",delegate{var macro=new Macro{RandomSeed=314159,Steps=new List<Step>{new Step{Kind=ActionKind.Repeat,Count=1,CountMax=10},new Step{Kind=ActionKind.TypeText,Text="x"},new Step{Kind=ActionKind.EndRepeat}}};var plan=Plan.Build(macro,directory);var first=new FakeHost();var second=new FakeHost();new Runner(first).Run(plan,4,20,CancellationToken.None).GetAwaiter().GetResult();new Runner(second).Run(plan,4,20,CancellationToken.None).GetAwaiter().GetResult();Check(first.Calls.Count==second.Calls.Count&&first.Calls.Count>=4&&first.Calls.Count<=40,"Seeded repeats differ");});
            test("Fixed seed reproduces bounded pointer jitter without changing source coordinates",delegate{using(var desktop=new TestDesktop()){var images=new ImageSession(desktop);var step=new Step{Pointer=PointerMode.Absolute,X=100,Y=-100,PositionJitter=5};images.SetRandomSeed(17);var first=Enumerable.Range(0,40).Select(i=>images.Position(step)).ToArray();images.SetRandomSeed(17);var second=Enumerable.Range(0,40).Select(i=>images.Position(step)).ToArray();Check(first.SequenceEqual(second)&&first.All(p=>p.X>=95&&p.X<=105&&p.Y>=-105&&p.Y<=-95)&&step.X==100,"Jitter not reproducible or out of range");}});
            test("Higher integrity target explains mismatch and equal/lower targets are allowed",delegate{Check(InputPermissions.Explain(0x2000,0x3000,false).Contains("administrator"),"Mismatch diagnostic missing");Check(InputPermissions.Explain(0x3000,0x3000,false)==null&&InputPermissions.Explain(0x3000,0x2000,false)==null&&InputPermissions.Explain(null,0x3000,false)==null&&InputPermissions.Explain(0x2000,0x3000,true)==null,"Permission decision incorrect");});
            test("Script compilation timeout is bounded without compiling or launching code",delegate{var pending=new TaskCompletionSource<bool>();try{Scripts.AwaitCompilation(pending.Task,15,CancellationToken.None).GetAwaiter().GetResult();throw new Exception("No compilation timeout");}catch(TimeoutException){}pending.SetResult(true);});
            test("Script compilation cancellation propagates without launching code",delegate{using(var cancel=new CancellationTokenSource()){cancel.Cancel();try{Scripts.AwaitCompilation(Task.FromResult(true),100,cancel.Token).GetAwaiter().GetResult();throw new Exception("No compilation cancellation");}catch(OperationCanceledException){}}});
            test("Script compiler failures preserve original diagnostics",delegate{var failed=new TaskCompletionSource<bool>();failed.SetException(new InvalidDataException("Line 4: syntax error"));try{Scripts.AwaitCompilation(failed.Task,100,CancellationToken.None).GetAwaiter().GetResult();throw new Exception("Compiler failure ignored");}catch(InvalidDataException error){Check(error.Message.Contains("Line 4"),"Compiler diagnostic lost");}});
            test("New behavior settings and seed survive workflow and player roundtrip",delegate{var macro=new Macro{RandomSeed=42,Steps=new List<Step>{new Step{Kind=ActionKind.TypeText,Text="é",InputHoldMs=80,TextIntervalMs=12,TextEntry=TextEntryMode.ClipboardPaste},new Step{Kind=ActionKind.IfImage,ToleranceMode=ImageToleranceMode.LegacyRgbPlusOne},new Step{Kind=ActionKind.EndIf}}};var decoded=Storage.Decode(Storage.Encode(macro));Check(decoded.RandomSeed==42&&decoded.Steps[0].InputHoldMs==80&&decoded.Steps[0].TextEntry==TextEntryMode.ClipboardPaste&&decoded.Steps[1].ToleranceMode==ImageToleranceMode.LegacyRgbPlusOne,"Behavior fields lost");string player=Path.Combine(directory,"behavior-player.exe");Portable.Export(Application.ExecutablePath,player,macro);Check(Portable.Read(player).RandomSeed==42,"Player seed lost");});
            test("Player verification rejects corrupt embedded references",delegate{var macro=new Macro{Steps=new List<Step>{new Step{Kind=ActionKind.ClickImage,ImageData="not base64"}}};try{Portable.Validate(macro,directory);throw new Exception("Corrupt image accepted");}catch(FormatException){} });
            for(int alignment=0;alignment<8;alignment++){int padding=alignment;test("Certificate-table player payload survives alignment "+padding,delegate{
                string player=Path.Combine(directory,"certificate-player-"+padding+".exe");Portable.Export(Application.ExecutablePath,player,new Macro{RandomSeed=63,Name="certificate fixture"});
                using(var stream=new FileStream(player,FileMode.Open,FileAccess.ReadWrite)){var reader=new BinaryReader(stream,System.Text.Encoding.UTF8,true);var writer=new BinaryWriter(stream,System.Text.Encoding.UTF8,true);stream.Position=0x3c;long pe=reader.ReadUInt32();stream.Position=pe+24;int magic=reader.ReadUInt16();long entry=pe+24+(magic==0x10b?128:144);long certificate=stream.Length+padding;stream.Position=entry;writer.Write((uint)certificate);writer.Write((uint)16);stream.Position=stream.Length;writer.Write(new byte[padding]);writer.Write(16);writer.Write((short)0x200);writer.Write((short)2);writer.Write(new byte[8]);}
                var restored=Portable.Read(player);Check(restored!=null&&restored.RandomSeed==63,"Certificate footer hid payload");string exported=Path.Combine(directory,"reexport-certificate-"+padding+".exe");Portable.Export(player,exported,new Macro{Name="replacement"});Check(Portable.Read(exported).Name=="replacement","Re-export failed to remove stale certificate");
            });}
            test("Malformed executable certificate table is rejected",delegate{string player=Path.Combine(directory,"bad-certificate.exe");Portable.Export(Application.ExecutablePath,player,new Macro());using(var stream=new FileStream(player,FileMode.Open,FileAccess.ReadWrite)){var reader=new BinaryReader(stream,System.Text.Encoding.UTF8,true);var writer=new BinaryWriter(stream,System.Text.Encoding.UTF8,true);stream.Position=0x3c;long pe=reader.ReadUInt32();stream.Position=pe+24;int magic=reader.ReadUInt16();stream.Position=pe+24+(magic==0x10b?128:144);writer.Write(uint.MaxValue);writer.Write((uint)16);}try{Portable.Read(player);throw new Exception("Invalid certificate bounds accepted");}catch(InvalidDataException){}});
            test("Hidden randomization editor saves seed without modifying the active theme",delegate{string style=UiTheme.Style;using(var form=new RandomizationForm(42)){var controls=form.Controls.Cast<Control>().SelectMany(c=>Descendants(c)).ToArray();Check(controls.OfType<NumericUpDown>().Single().Value==42&&!form.Visible,"Seed editor changed initial value");}Check(UiTheme.Style==style,"Seed editor changed palette");});
            test("New input ranges and enums reject malformed workflows",delegate{foreach(var step in new[]{new Step{InputHoldMs=-1},new Step{InputHoldMs=60001},new Step{TextIntervalMs=60001},new Step{TextEntry=(TextEntryMode)17},new Step{ToleranceMode=(ImageToleranceMode)17}}){try{Storage.Validate(new Macro{Steps=new List<Step>{step}});throw new Exception("Invalid behavior accepted");}catch(InvalidDataException){}}});
        }
    }
}

